{
  "propositions": [
    {
      "text": "Meta Platforms Ireland Limited announced it will appeal the DPC's decision.",
      "exactQuote": "Meta announced that it will be appealing the DPC's decision",
      "blockId": "c-law-004#block-4"
    },
    {
      "text": "Meta will seek a stay with the courts to pause the implementation of applicable deadlines.",
      "exactQuote": "will seek a stay with the courts to pause the implementation of applicable deadlines",
      "blockId": "c-law-004#block-4"
    },
    {
      "text": "Meta has consistently argued that its data transfers were lawful under the Standard Contractual Clauses framework.",
      "exactQuote": "Meta has consistently argued that its data transfers were lawful under the Standard Contractual Clauses framework",
      "blockId": "c-law-004#block-4"
    },
    {
      "text": "Meta is not the only company affected by the Schrems II ruling.",
      "exactQuote": "Meta is not the only company affected by the Schrems II ruling",
      "blockId": "c-law-004#block-6"
    },
    {
      "text": "The fundamental question of whether US surveillance law provides 'essentially equivalent' protection to EU law affects all transatlantic data transfers.",
      "exactQuote": "The fundamental question of whether US surveillance law provides \"essentially equivalent\" protection to EU law affects all transatlantic data transfers",
      "blockId": "c-law-004#block-6"
    },
    {
      "text": "The decision came amid ongoing negotiations for a new EU-US Data Privacy Framework.",
      "exactQuote": "The decision came amid ongoing negotiations for a new EU-US Data Privacy Framework",
      "blockId": "c-law-004#block-6"
    },
    {
      "text": "The EU-US Data Privacy Framework was subsequently adopted as an adequacy decision in July 2023.",
      "exactQuote": "subsequently adopted as an adequacy decision in July 2023",
      "blockId": "c-law-004#block-6"
    },
    {
      "text": "According to enforcementtracker.com, this was the largest GDPR fine ever imposed.",
      "exactQuote": "According to enforcementtracker.com, this was the largest GDPR fine ever imposed",
      "blockId": "c-law-004#block-8"
    },
    {
      "text": "Prior major GDPR fines included Amazon (€746 million, Luxembourg, 2021).",
      "exactQuote": "Prior major GDPR fines included: Amazon (€746 million, Luxembourg, 2021)",
      "blockId": "c-law-004#block-8"
    },
    {
      "text": "Prior major GDPR fines included WhatsApp (€225 million, Ireland, 2021).",
      "exactQuote": "WhatsApp (€225 million, Ireland, 2021)",
      "blockId": "c-law-004#block-8"
    },
    {
      "text": "Prior major GDPR fines included Meta's separate €390 million fine (Ireland, January 2023) for GDPR violations related to personalized advertising legal basis.",
      "exactQuote": "Meta's separate €390 million fine (Ireland, January 2023) for GDPR violations related to personalized advertising legal basis",
      "blockId": "c-law-004#block-8"
    },
    {
      "text": "In January 2023, the Irish DPC fined Meta Platforms Ireland Limited €390 million total.",
      "exactQuote": "In January 2023, the Irish DPC fined Meta Platforms Ireland Limited €390 million total",
      "blockId": "c-law-004#block-10"
    },
    {
      "text": "The €390 million fine comprised €210 million for Facebook and €180 million for Instagram.",
      "exactQuote": "€210 million for Facebook and €180 million for Instagram",
      "blockId": "c-law-004#block-10"
    },
    {
      "text": "The violations related to the legal basis for personalized advertising (Articles 5(1)(a), 6(1), 12, 13(1)(c) GDPR).",
      "exactQuote": "violations related to the legal basis for personalized advertising (Articles 5(1)(a), 6(1), 12, 13(1)(c) GDPR)",
      "blockId": "c-law-004#block-10"
    },
    {
      "text": "Meta had relied on 'contractual necessity' (Article 6(1)(b)) as the legal basis.",
      "exactQuote": "Meta had relied on \"contractual necessity\" (Article 6(1)(b)) as the legal basis",
      "blockId": "c-law-004#block-10"
    },
    {
      "text": "The EDPB determined that contractual necessity was not valid and that user consent was required.",
      "exactQuote": "the EDPB determined this was not valid and that user consent was required",
      "blockId": "c-law-004#block-10"
    },
    {
      "text": "Meta assumed that the acceptance of the updated terms of use constituted a contract between Meta and the user.",
      "exactQuote": "Meta assumed that the acceptance of the updated terms of use constituted a contract between Meta and the user",
      "blockId": "c-law-004#block-11"
    },
    {
      "text": "Meta assumed that the processing of the data would be necessary for the provision as well as the improvement of the services.",
      "exactQuote": "since the processing of the data would be necessary for the provision as well as the improvement of the services",
      "blockId": "c-law-004#block-11"
    },
    {
      "text": "The complaints that triggered both the January 2023 advertising decision and the May 2023 data transfers decision were filed by privacy activist Max Schrems and his organization noyb.",
      "exactQuote": "The complaints that triggered both the January 2023 advertising decision and the May 2023 data transfers decision were filed by privacy activist Max Schrems and his organization noyb (None Of Your Business)",
      "blockId": "c-law-004#block-13"
    },
    {
      "text": "Schrems has been the driving force behind the legal challenges to EU-US data transfers since 2013.",
      "exactQuote": "Schrems has been the driving force behind the legal challenges to EU-US data transfers since 2013",
      "blockId": "c-law-004#block-13"
    },
    {
      "text": "The European Commission adopted an adequacy decision for the EU-US Data Privacy Framework on 10 July 2023.",
      "exactQuote": "The European Commission adopted an adequacy decision for the EU-US Data Privacy Framework on 10 July 2023",
      "blockId": "c-law-004#block-15"
    },
    {
      "text": "The adequacy decision potentially resolves the legal basis for transatlantic data transfers going forward.",
      "exactQuote": "potentially resolving the legal basis for transatlantic data transfers going forward",
      "blockId": "c-law-004#block-15"
    },
    {
      "text": "Privacy advocates have signaled they may challenge this framework as well.",
      "exactQuote": "though privacy advocates have signaled they may challenge this framework as well",
      "blockId": "c-law-004#block-15"
    }
  ]
}
